            return resolved;
        }
    } catch (e) {
        console.warn('fetchParentContextToInput: could not resolve field "' + fieldName + '" — using as provided');
    }

    return fieldName;
}

function resolveFetchFields(fields, projectKey, fieldLabels, shouldResolve, tracker) {
    var resolved = [];
