        assert.ok(capturedJql.indexOf('{parentKey}') === -1, 'placeholder removed: ' + capturedJql);
    });

    test('passes configured fields to jira_search_by_jql', function() {
        var capturedFields = null;
        var m = loadFetchParentContext({
