    if (t && typeof t === 'object' && !Array.isArray(t) && t.fields && typeof t.fields === 'object' &&
        !_isAdoFields(t.fields)) return t;
    var n = normalizeTicket(t);
    if (!n) return null;
    var fields = {
        summary: n.title,
        status: { name: n.status },
        labels: n.labels || [],
        issuetype: { name: n.issueType },
        description: n.description,
