 */
function renderQuestionsMarkdown(itemKey, qResults, answerField) {
    var qMd = '\\n\\n---\\n\\n## Questions & Answers (' + itemKey + ')\\n\\n';
    for (var q = 0; q < qResults.length; q++) {
