function appendChildQuestions(filePath, itemKey, ctxFile, childQuestionsCfg, tracker, qResults, answerField) {
    if (qResults.length === 0) return;
    var qMd = renderQuestionsMarkdown(itemKey, qResults, answerField);
    appendQuestionsToFile(filePath, qMd, ctxFile, qResults.length);
}

