        jqlTemplate: cfg.jql || DEFAULT_JQL,
        siblingFields: cfg.siblingFields || cfg.fields || buildDefaultFields(projectConfig),
        contexts: cfg.contexts || DEFAULT_CONTEXTS,
        fieldLabels: cfg.fieldLabels || {},
